int blkcg_init_queue(struct request_queue *q)
{
    struct blkg_policy_data *pd;
    struct blkg *blkg;
    int ret = 0;

    blkg = kzalloc_node(sizeof(*blkg), GFP_KERNEL, q->node);
    if (!blkg)
        return -ENOMEM;

    blkg->q = q;
    blkg->parent = NULL;
    blkg->plid = 0;

    pd = blkg->pd[0] = blkg_policy_data_alloc(q, 0, blkg);
    if (!pd) {
        ret = -ENOMEM;
        goto err_free_blkg;
    }

    ret = blkg_init(q, blkg);
    if (ret)
        goto err_free_pd;

    ret = blkg_register(q, blkg);
    if (ret)
        goto err_free_pd;

    return 0;

err_free_pd:
    blkg_policy_data_free(pd);
err_free_blkg:
    kfree(blkg);
    return ret;
}

int blkcg_init_queue(struct request_queue *q)
{
    struct blkcg *root_blkg = NULL;
    struct blkg_policy_data *pd = NULL;
    int ret = 0;

    radix_tree_preload(GFP_KERNEL);
    root_blkg = kzalloc(sizeof(*root_blkg), GFP_KERNEL);
    if (!root_blkg) {
        ret = -ENOMEM;
        goto fail;
    }

    pd = kzalloc(sizeof(*pd), GFP_KERNEL);
    if (!pd) {
        ret = -ENOMEM;
        goto fail;
    }

    if (blk_throtl_init(q)) {
        ret = -EINVAL;
        goto fail;
    }

    q->blkcg = root_blkg;
    root_blkg->pd = pd;

    radix_tree_preload_end();
    return 0;

fail:
    radix_tree_preload_end();
    kfree(pd);
    kfree(root_blkg);
    return ret;
}

int blkcg_init_queue(struct request_queue *q)
{
    struct blkg *blkg;
    int ret;

    blkg = kzalloc_node(sizeof(*blkg), GFP_KERNEL, queue_to_node(q));
    if (!blkg)
        return -ENOMEM;

    spin_lock_init(&blkg->lock);
    blkg->q = q;

    ret = radix_tree_preload(GFP_KERNEL);
    if (ret) {
        kfree(blkg);
        return ret;
    }

    if (!q->blkg_root) {
        q->blkg_root = blkg;
        ret = 0;
    } else {
        ret = blkg_init_throttle(blkg);
        if (ret) {
            radix_tree_delete(&q->blkg_table, 0);
            blkg_destroy(blkg);
            blkg = NULL;
        }
    }

    radix_tree_preload_end();
    return ret;
}

int blkcg_init_queue(struct request_queue *q)
{
    struct blkg *blkg;
    int ret;

    blkg = kzalloc_node(sizeof(*blkg), GFP_KERNEL, queue_to_node(q));
    if (!blkg)
        return -ENOMEM;

    blkg->q = q;
    spin_lock_init(&blkg->lock);

    if (!blkg_root) {
        blkg_root = blkg;
        blkg->parent = NULL;
    } else {
        blkg->parent = blkg_root;
        blkg_root->children++;
    }

    ret = blkg_throtl_init(blkg);
    if (ret) {
        blkg_destroy(blkg);
        return ret;
    }

    return 0;
}

#include <linux/radix-tree.h>
#include <linux/blkdev.h>
#include <linux/slab.h>

int blkcg_init_queue(struct request_queue *q)
{
    struct blkg_policy_data *pd;
    int ret = 0;

    pd = kmem_cache_zalloc(blkcg_pol_sec_data, GFP_KERNEL);
    if (!pd)
        return -ENOMEM;

    radix_tree_preload(GFP_KERNEL);
    spin_lock_init(&q->blkcg_root_lock);
    q->blkcg_root = pd;
    pd->q = q;

    ret = blk_throtl_init(q);
    if (ret) {
        kmem_cache_free(blkcg_pol_sec_data, pd);
        return ret;
    }

    radix_tree_preload_end();
    return 0;
}
